-- YG-1368 platform dışı işlem ve geçici referans; YG-1284 normalleşme testi ve uzlaştırma kapısı.
CREATE TABLE kesinti (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), tur text NOT NULL CHECK (tur IN ('Kesinti', 'Onaylı İstisna')), neden text NOT NULL, kapsam text NOT NULL, durum text NOT NULL CHECK (durum IN ('Onayda', 'Açık', 'Reddedildi', 'Kapandı')), baslangic timestamptz NOT NULL DEFAULT now(), bitis timestamptz, normallesme jsonb, acan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), kapatan_ref text REFERENCES kullanici_hesabi (kimlik));
CREATE TABLE gecici_referans (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), referans text NOT NULL UNIQUE CHECK (referans ~ '^GR-[0-9]{4}-[0-9]{5}$'), kesinti_ref uuid NOT NULL REFERENCES kesinti (kimlik), sorumlu_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), kullanildi boolean NOT NULL DEFAULT false, iptal boolean NOT NULL DEFAULT false, kanal text, yetkili_kisi text, asgari_veri text, saklama_yeri text, dosya_ref uuid REFERENCES dosya (kimlik), islem_zamani timestamptz, geri_giris_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON kesinti, gecici_referans TO yatonet_uygulama;
